/* SPDX-License-Identifier: LGPL-2.1-or-later */

#include "alloc-util.h"
#include "escape.h"
#include "tests.h"

TEST(cunescape_u_and_U_agree_on_noncharacters) {
        /* The 16-bit and 32-bit escapes spell the same code point and must accept or reject it
         * consistently. */
        static const struct {
                const char *u;
                const char *U;
        } table[] = {
                { "\\ufffe", "\\U0000fffe" },
                { "\\uffff", "\\U0000ffff" },
                { "\\ufdd0", "\\U0000fdd0" },
                { "\\ud800", "\\U0000d800" },
                { "\\u00df", "\\U000000df" },
        };

        FOREACH_ELEMENT(t, table) {
                _cleanup_free_ char *a = NULL, *b = NULL;
                int ra, rb;

                ra = cunescape(t->u, 0, &a);
                rb = cunescape(t->U, 0, &b);

                log_info("%s -> %i, %s -> %i", t->u, ra, t->U, rb);
                ASSERT_EQ(ra >= 0, rb >= 0);
        }
}

DEFINE_TEST_MAIN(LOG_INFO);

